from pathlib import Path
p=Path('src/components/public.tsx');s=p.read_text(encoding='utf-8')
old='<div className="home-hero-photo"><Photo name="home-hero" alt="A guest enjoying a vibrant live event"/></div>'
new='''<div className="home-hero-photo"><Photo name="home-hero" alt="A guest enjoying a vibrant live event"/><span className="hero-handwriting">More<br/>Events.<br/>Brighter<br/>People</span><button className="home-hero-play" aria-label="Explore event inspiration" onClick={()=>document.querySelector(".home-inspiration")?.scrollIntoView({behavior:"smooth"})}><Play fill="currentColor" size={14}/></button><Link href="/events/neon-nights" className="hero-floating-event"><Photo name="avatar-0"/><span><b>Live Event Tonight</b><strong>Sunset Music Festival</strong><small>Cape Town</small><small>🎟 2,312 going</small></span><Heart size={10}/></Link><Link href="/onboarding/experience" className="hero-floating-plan"><IconTile icon={CalendarDays}/><span><b>Plan Your Event</b><small>From idea to incredible</small><small>AI-powered planning</small></span><Heart size={10}/></Link></div>'''
assert old in s
s=s.replace(old,new)
p.write_text(s,encoding='utf-8')
p=Path('src/app/globals.css');s=p.read_text(encoding='utf-8')
s+='''\n.video-caption{opacity:1}.video-photo:before{content:"";position:absolute;inset:40% 0 0;z-index:1;background:linear-gradient(transparent,#08132ac9);pointer-events:none}\n@media(min-width:701px){.hero-handwriting{position:absolute;top:13%;left:10%;font-family:cursive;font-style:italic;font-size:1.85em;line-height:1.02;color:white;transform:rotate(-9deg)}.home-hero-play{position:absolute;top:52%;left:22%;width:3.1em;height:3.1em;display:grid;place-items:center;border:2px solid #c9aaff;border-radius:50%;background:#783effa8;color:white}.hero-floating-event,.hero-floating-plan{position:absolute;right:6%;width:12.3em;background:#fff;border-radius:1em;display:flex;align-items:center;gap:.7em;padding:.7em;box-shadow:0 6px 25px #30117522}.hero-floating-event{top:23%;height:6em}.hero-floating-plan{top:60%;height:5.7em}.hero-floating-event>.photo{width:3.7em;height:4.6em;border-radius:.6em;object-fit:cover}.hero-floating-event span,.hero-floating-plan span{display:flex;flex-direction:column;gap:.25em}.hero-floating-event b,.hero-floating-plan b{font-size:.6em}.hero-floating-event strong{font-size:.58em}.hero-floating-event small,.hero-floating-plan small{font-size:.5em}.hero-floating-event>svg,.hero-floating-plan>svg{position:absolute;right:.7em;top:.8em;color:#ee62a8}.hero-floating-plan .icon-tile{width:2.5em;height:2.5em;background:#0c6aff;color:white;box-shadow:0 0 0 3px #d7e8ff;border-radius:.6em}.hero-floating-plan .icon-tile svg{width:1.8em;height:1.8em}}\n@media(max-width:700px){.hero-handwriting,.home-hero-play,.hero-floating-event,.hero-floating-plan{display:none}}\n'''
p.write_text(s,encoding='utf-8')
